export const BODY: string = "\n<p>تحويل JPG إلى PNG عمل بسيط، لكن يستحق فعله بشكل صحيح. التحويل السيئ يضاعف حجم الملف دون أي فائدة.</p>\n<p>العملية تستغرق ثوانٍ لكل ملف، ويمكنك تحويل حتى عشرين صورة دفعة واحدة. التحويل يحدث على جهازك دون رفع إلى خادم.</p>\n<p>يمر هذا الدليل بكل خطوة، ويشرح ما يجب مراجعته قبل استخدام النتيجة.</p>\n<h2 id=\"before-you-start\">قبل أن تبدأ: وضّح سبب تحويلك</h2>\n<p>قبل أن تبدأ، وضّح سبب تحويلك: هل تحتاج إلى تحرير متكرر، أم نصوص حادة، أم أرشفة دون فقدان؟ السبب يحدد ما إذا كان التحويل يستحق.</p>\n<p>إذا كان هدفك فقط مشاركة صورة أو رفعها إلى موقع، فلا تحوّل. الملف الأكبر لا يضيف أي جودة.</p>\n<h2 id=\"step-1-open-tool\">الخطوة 1: افتح أداة JPG إلى PNG</h2>\n<p>افتح <a href=\"/ar/tahwil-jpg-ila-png/\">أداة JPG إلى PNG</a> في متصفحك. تعمل الأداة بالكامل على جهازك دون رفع الصور إلى أي خادم.</p>\n<p>لا حاجة إلى حساب أو تثبيت. افتح الصفحة وابدأ فورًا، وستبقى صورك خاصة طوال العملية.</p>\n<h2 id=\"step-2-upload\">الخطوة 2: ارفع ملفات JPG</h2>\n<p>ارفع ملفات JPG: أسقطها في منطقة الرفع أو اخترها من جهازك. تُقبل ملفات JPG بأي حجم معقول.</p>\n<p>إذا رفعت عدة ملفات، فستظهر كل واحدة في قائمة. يمكنك تحويلها كلها دفعة واحدة.</p>\n<h2 id=\"step-3-convert\">الخطوة 3: حوّل الملفات</h2>\n<p>حوّل الملفات: اضغط زر التحويل وانتظر حتى تنتهي الأداة. التحويل إلى PNG سريع لأنه يعيد ترميز البيانات دون حسابات معقدة.</p>\n<p>لا يوجد منزلق جودة لأن PNG ضغط دون فقدان. كل بكسل يُحفظ بدقة كاملة تلقائيًا.</p>\n<h2 id=\"step-4-compare\">الخطوة 4: قارن النتيجة</h2>\n<p>قارن النتيجة: افتح ملف PNG المحوّل وقارنه بالأصل. تأكد من أن الألوان صحيحة والنصوص حادة والتفاصيل واضحة.</p>\n<p>إذا بدت النتيجة مطابقة للأصل، فهي جاهزة. التحويل الجيد لا يغيّر الصورة، فقط الصيغة.</p>\n<h2 id=\"step-5-download\">الخطوة 5: نزّل ملفات PNG</h2>\n<p>نزّل ملفات PNG: اضغط زر التنزيل واحفظ الملفات في مجلد جديد. إذا كانت عدة ملفات، فستنزّل كملف ZIP واحد.</p>\n<p>فك ضغط الملف وراجع النتائج. تحقق من أن كل ملف موجود ويبدو صحيحًا.</p>\n<ol>\n<li>ارفع ملفات JPG.</li>\n<li>حوّل الملفات.</li>\n<li>قارن النتيجة بالأصل.</li>\n<li>نزّل ملفات PNG.</li>\n</ol>\n<h2 id=\"converting-a-batch\">كيف تحوّل دفعة من عشرين؟</h2>\n<p>لتحويل دفعة من عشرين، ارفع كل الملفات دفعة واحدة وحوّلها بإعدادات موحدة. الأداة تحوّل الدفعة كاملة وتنزّلها كملف ZIP.</p>\n<p>توقع أن يكون ملف ZIP كبيرًا. PNG أكبر من JPG، ودفعة من 20 صورة قد تزن مئات الميغابايت.</p>\n<h2 id=\"checking-file-size\">كيف تراجع حجم الملف قبل إرساله؟</h2>\n<p>لمراجعة حجم الملف قبل الإرسال، افحص حجم PNG المحوّل وقارنه بحد الرفع في الوجهة. إذا تجاوز الحد، فحوّل إلى WebP بدل ذلك.</p>\n<p>لا ترسل ملفًا أكبر من اللازم. الحجم الكبير يبطئ الرفع وقد يُرفض من البوابة.</p>\n<h2 id=\"using-png-for-editing\">كيف تستخدم PNG في التحرير؟</h2>\n<p>لاستخدام PNG في التحرير، حوّل إلى PNG قبل التحرير المكثف. حرر النسخة PNG، ثم صدّر النتيجة النهائية بصيغة مناسبة.</p>\n<p>بهذا تتجنب فقدان الجودة في كل جولة تحرير. PNG هو صيغة العمل، وJPG أو WebP هما صيغتا التسليم.</p>\n<h2 id=\"fixing-problems\">كيف تحل المشاكل الشائعة؟</h2>\n<p>لحل المشاكل الشائعة، افحص السبب أولًا. الملف الذي يفشل في التحويل قد يكون تالفًا، والألوان المتغيرة قد تعني نمط CMYK.</p>\n<p>أعد التحويل من الملف الأصلي. وإذا استمرت المشكلة، فحوّل الملف أولًا إلى RGB ثم إلى PNG.</p>\n<h2 id=\"mobile-tips\">نصائح للهواتف والأجهزة اللوحية</h2>\n<p>نصائح للهواتف والأجهزة اللوحية: افتح الأداة في المتصفح وارفع الصور من معرضك. التحويل يعمل على الهاتف دون تثبيت أي تطبيق.</p>\n<p>للدفعات الكبيرة على الهاتف، قسّمها إلى مجموعات صغيرة. المجموعات الصغيرة أسرع وأقل عرضة للفشل.</p>\n<h2 id=\"old-family-photos\">كيف تحوّل صورًا عائلية قديمة؟</h2>\n<p>لتحويل صور عائلية قديمة، امسحها بدقة عالية أولًا ثم حوّلها إلى PNG للأرشفة. PNG يحفظ التفاصيل دون فقدان إضافي.</p>\n<p>احتفظ بالنسخ PNG في مجلد أرشيف منفصل. الأرشيف دون فقدان يحفظ ذكريات العائلة بأفضل جودة ممكنة.</p>\n<h2 id=\"screenshots-for-manual\">كيف تحوّل لقطات لدليل إرشادي؟</h2>\n<p>لتحويل لقطات لدليل إرشادي، حوّلها إلى PNG قبل إضافة التعليقات والأسهم. PNG يحفظ النصوص والحواف بوضوح أكبر.</p>\n<p>أضف التعليقات بعد التحويل لا قبله. التعليقات على PNG تبقى حادة وواضحة في الدليل النهائي.</p>\n<h2 id=\"images-for-designer\">كيف تحوّل صورًا لمصمم؟</h2>\n<p>لتحويل صور لمصمم، حوّلها إلى PNG وأرسلها مع ملاحظات واضحة. المصمم يحتاج إلى ملفات عالية الجودة للعمل عليها.</p>\n<p>اذكر الغرض من كل صورة في رسالتك. السياق الواضح يساعد المصمم على استخدام الصور بشكل صحيح.</p>\n<h2 id=\"product-shots-editing\">كيف تحوّل صور منتجات للتحرير؟</h2>\n<p>لتحويل صور منتجات للتحرير، حوّلها إلى PNG قبل التحرير. حرر النسخة PNG، ثم صدّر النتيجة النهائية بصيغة مناسبة للنشر.</p>\n<p>بهذا تتجنب فقدان الجودة في كل جولة تحرير. صور المنتجات تحتاج إلى أقصى جودة ممكنة.</p>\n<h2 id=\"images-for-print\">كيف تحوّل صورًا للطباعة؟</h2>\n<p>لتحويل صور للطباعة، حوّلها إلى PNG إذا كانت رسومًا أو نصوصًا. الحواف الحادة تطبع بشكل أنظف من JPG.</p>\n<p>للصور الفوتوغرافية المطبوعة، استخدم JPG بجودة عالية. الطباعة تحتاج دقة كاملة، والصيغة أقل أهمية من الدقة.</p>\n<h2 id=\"images-for-school-assignment\">كيف تحوّل صورًا لمهمة مدرسية؟</h2>\n<p>لتحويل صور لمهمة مدرسية، حوّلها إلى PNG إذا كانت تحتوي على نصوص أو رسوم. النص يبقى حادًا وواضحًا في المهمة.</p>\n<p>وللتفاصيل الكاملة، اقرأ <a href=\"/ar/blog/dalil-tahwil-jpg-ila-png/\">الدليل الكامل لتحويل JPG إلى PNG</a> و<a href=\"/ar/blog/jpg-vs-png-al-shafafiyya/\">JPG مقابل PNG والشفافية</a>، أو حوّل إلى WebP باستخدام <a href=\"/ar/tahwil-jpg-ila-webp/\">محول JPG إلى WebP</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"كم ملف JPG يمكنني تحويله إلى PNG دفعة واحدة؟","answer":"يمكنك تحويل حتى 20 ملفًا دفعة واحدة. ارفعها كلها وحوّلها بإعدادات موحدة ونزّلها كملف ZIP واحد."},{"question":"هل يمكنني تحويل JPG إلى PNG دون أن يكبر الملف؟","answer":"لا، لا يمكن تجنب النمو: PNG ضغط دون فقدان ويحفظ كل بكسل بدقة. الملف سيكون أكبر دائمًا من JPG الأصلي."},{"question":"هل يعمل تحويل JPG إلى PNG دون اتصال بالإنترنت؟","answer":"نعم، التحويل يعمل بالكامل في متصفحك دون اتصال بالخادم. بعد تحميل الصفحة، يعمل كل شيء دون إنترنت."},{"question":"هل سيفتح ملف PNG في فوتوشوب وكانفا؟","answer":"نعم، PNG يعمل في فوتوشوب وكانفا وكل برامج التصميم. إنها صيغة قياسية مدعومة في كل مكان."},{"question":"ماذا أفعل إذا كان ملف PNG كبيرًا جدًا للرفع؟","answer":"إذا كان PNG كبيرًا جدًا للرفع، فحوّل إلى WebP بدل ذلك أو اضغط PNG بعد التحويل. WebP أصغر بكثير بالجودة نفسها."},{"question":"هل يمكنني تحويل لقطة JPG إلى PNG للتعليق عليها؟","answer":"نعم، يمكنك تحويل لقطة JPG إلى PNG للتعليق عليها. PNG يحفظ النصوص والحواف بوضوح أكبر، وهو مناسب للتعليقات والأسهم."}];
